p { margin: 0 0 1em; }

a { color: inherit; text-underline-offset: 0.15em; }
a:hover { color: var(--c-pink); }

img, svg { max-width: 100%; }

.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.18em;
  font: 900 32px/1 var(--f-display);
  letter-spacing: -0.05em;
  color: inherit;
  white-space: nowrap;
}
.logo__mark {
  display: inline-grid;
  place-items: center;
  width: 1.05em;
  height: 1.05em;
  border-radius: 50% 50% 50% 12%;
  background: var(--c-sun);
  color: var(--c-night);
  font-size: 0.8em;
  letter-spacing: 0;
}

