import { Controller } from "@hotwired/stimulus"

// Option rows of the question form: "Add option" appends a row with the next
// number, the ✕ button removes a row. Rows are renumbered so the labels
// ("Option 1", "Option 1 is correct", …) and the param indexes stay in order.
export default class extends Controller {
  static targets = ["list", "row", "template"]

  add() {
    const fragment = this.templateTarget.content.cloneNode(true)
    const row = fragment.querySelector("[data-option-rows-target='row']")
    this.listTarget.appendChild(fragment)
    this.renumber()
    row.querySelector("[data-role='title']").focus()
  }

  remove(event) {
    const row = event.currentTarget.closest("[data-option-rows-target='row']")
    const next = row.nextElementSibling || row.previousElementSibling
    row.remove()
    this.renumber()
    if (next) next.querySelector("[data-role='title']")?.focus()
  }

  renumber() {
    this.rowTargets.forEach((row, index) => {
      const number = index + 1
      const title = row.querySelector("[data-role='title']")
      const correct = row.querySelector("[data-role='correct']")
      const titleLabel = row.querySelector("[data-role='title-label']")
      const correctLabel = row.querySelector("[data-role='correct-label']")
      const removeButton = row.querySelector("[data-role='remove']")

      title.id = `question_option_rows_${index}_title`
      title.name = `question[option_rows][${index}][title]`
      correct.id = `question_option_rows_${index}_correct`
      correct.name = `question[option_rows][${index}][correct]`
      titleLabel.htmlFor = title.id
      titleLabel.textContent = `Option ${number}`
      correctLabel.textContent = `Option ${number} is correct`
      removeButton.setAttribute("aria-label", `Remove option ${number}`)
      removeButton.title = `Remove option ${number}`
    })
  }
}
EOF
